import heapq

def shortest_path(graph, src, dst):
    if src == dst:
        return [src]
    if src not in graph:
        return []

    # (total_weight, path_so_far, node)
    heap = [(0, [src], src)]
    best = {}  # finalized nodes -> True

    while heap:
        dist, path, node = heapq.heappop(heap)
        if node in best:
            continue
        best[node] = True
        if node == dst:
            return path
        for nbr, w in graph.get(node, {}).items():
            if nbr in best:
                continue
            heapq.heappush(heap, (dist + w, path + [nbr], nbr))

    return []
```

Notes: it's Dijkstra where the priority key is `(distance, path)`, so ties in weight are broken by the lexicographically smallest path. This is correct because with positive weights two equal-weight paths to the same node can never have one as a prefix of the other, so appending a node preserves their lexicographic order.
